import { useGesture } from '@use-gesture/react';
import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';

import { fitBetween } from '../functions/fitBetween.js';
import { getDraggableBounds } from '../functions/get-draggable-bounds.js';

export interface DragBounds {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/**
 * Add the drag and drop logic into elementRef.
 *
 * @param elementRef - Ref of the element container, that will be dragged
 * @param boundRef - Ref defining the element bounds
 * @param initialPosition - Initial position of the element
 */
export function useDragElement(
  elementRef: React.RefObject<HTMLDivElement>,
  boundRef: React.RefObject<HTMLDivElement>,
  initialPosition: Pick<DragBounds, 'top' | 'right'>,
  expanded: boolean,
) {
  const [isDragging, setIsDragging] = useState<boolean>(false);
  /** Element reference that will trigger all useGesture logic */
  const triggerDragRef = useRef<HTMLButtonElement>(null);
  /** Current relative top and right position of the element */
  const [currentPosition, setCurrentPosition] =
    useState<Pick<DragBounds, 'top' | 'right'>>(initialPosition);
  /** Last offset between the initial position of the element and the position after the last drag event */
  const [lastIdlePosition, setLastIdlePosition] =
    useState<Pick<DragBounds, 'top' | 'right'>>(initialPosition);

  const maxBounds = getDraggableBounds(elementRef, boundRef);

  useLayoutEffect(() => {
    // if bounds change, meaning the bounds element or the draggable element change it's size, it should readjust the position
    const right = fitBetween(currentPosition.right, 0, maxBounds.right);
    const top = fitBetween(currentPosition.top, 0, maxBounds.top);

    setCurrentPosition({ right, top });
    setLastIdlePosition({ right, top });
  }, [maxBounds.right, maxBounds.top, expanded]);

  useEffect(() => {
    if (elementRef.current) {
      const { top, right } = initialPosition;
      setCurrentPosition({ right, top });
      setLastIdlePosition({ right, top });
    }
  }, [initialPosition.top, initialPosition.right]);

  useEffect(() => {
    const { top, right } = currentPosition;

    if (elementRef.current) {
      elementRef.current.style.right = `${right}px`;
      elementRef.current.style.top = `${top}px`;
    }
  }, [elementRef.current, currentPosition.top, currentPosition.right]);

  useGesture(
    {
      onDrag: (event) => {
        /**
         * negative movedX - drag left
         * positive movedX - drag right
         * negative movedY - drag top
         * positive movedY - drag bottom
         */
        const [movedX, movedY] = event.movement;

        const x = lastIdlePosition.right - movedX;
        const y = lastIdlePosition.top + movedY;

        setIsDragging(true);

        const right = fitBetween(x, 0, maxBounds.right);
        const top = fitBetween(y, 0, maxBounds.top);

        setCurrentPosition({ right, top });
      },
      onDragEnd: () => {
        setLastIdlePosition(currentPosition);
        setIsDragging(false);
      },
    },
    {
      target: triggerDragRef,
      eventOptions: { passive: false },
      drag: { filterTaps: true },
    },
  );

  return { isDragging, triggerDragRef };
}
